import { html } from "lit";
import { expect, userEvent } from "storybook/test";
import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import comp from "./main.js";

const squiz = squizStoryRenderer(comp.main);

function withPageContent(args) {
  return html`
    <div>
      ${squiz(args)}
      <main>
        <div class="content-area">
          <p>Some sample content</p>
        </div>
      </main>
    </div>
  `;
}

export default {
  title: "dxp components/Header",
  parameters: {
    noContentArea: true,
    controls: {
      expanded: true,
      sort: "requiredFirst",
    },
  },
};

const argTypes = {
  variant: {
    control: "select",
    options: ["nt-gov-au", "agency-internet"],
    table: { category: "1. Layout" },
  },
  agencyName: {
    control: "text",
    if: { arg: "variant", neq: "nt-gov-au" },
    table: { category: "2. Agency Variant Only" },
  },
  agencyLinkType: {
    control: "select",
    options: ["matrix-asset", "custom-url"],
    if: { arg: "variant", neq: "nt-gov-au" },
    table: { category: "2. Agency Variant Only" },
  },
  agencyLinkAsset: {
    control: "text",
    if: { arg: "agencyLinkType", eq: "matrix-asset" },
    table: { category: "2. Agency Variant Only" },
  },
  agencyCustomUrl: {
    control: "text",
    if: { arg: "agencyLinkType", eq: "custom-url" },
    table: { category: "2. Agency Variant Only" },
  },
  links: {
    control: "object",
    if: { arg: "variant", neq: "agency-internet" },
    table: { category: "3. Navigation" },
  },
};

const ntGovAuArgs = {
  variant: "nt-gov-au",
  links: [
    {
      label: "Find online services",
      linkType: "custom-url",
      customUrl: "https://nt.gov.au/services",
    },
    {
      label: "Contacts",
      linkType: "custom-url",
      customUrl: "https://nt.gov.au/contacts",
    },
  ],
};
const ntGovAuHtml = await squiz.markup(ntGovAuArgs);

export const NtGovAu = {
  name: "NTG",
  render: (args) => withPageContent(args),
  args: ntGovAuArgs,
  argTypes,
  parameters: {
    docs: { source: { code: ntGovAuHtml, language: "html", type: "code" } },
  },
  play: async ({ canvasElement }) => {
    const root = canvasElement.querySelector("[data-header-root]");
    const searchToggle = root?.querySelector("[data-header-search-toggle]");
    const searchPanel = root?.querySelector("[data-header-search-panel]");
    const searchClose = root?.querySelector("[data-header-search-close]");
    const menuToggle = root?.querySelector("[data-header-menu-toggle]");
    const menuPanel = root?.querySelector("[data-header-menu-panel]");
    const menuClose = root?.querySelector("[data-header-menu-close]");

    await expect(root).toBeTruthy();
    await expect(searchToggle).toHaveAttribute("aria-expanded", "false");
    await expect(searchPanel?.hidden).toBe(true);
    await userEvent.click(searchToggle);
    await expect(searchToggle).toHaveAttribute("aria-expanded", "true");
    await expect(searchPanel?.hidden).toBe(false);
    await userEvent.click(searchClose);
    await expect(searchToggle).toHaveAttribute("aria-expanded", "false");
    await expect(searchPanel?.hidden).toBe(true);

    await expect(menuToggle).toHaveAttribute("aria-expanded", "false");
    await expect(menuPanel?.hidden).toBe(true);
    await userEvent.click(menuToggle);
    await expect(menuToggle).toHaveAttribute("aria-expanded", "true");
    await expect(menuPanel?.hidden).toBe(false);
    await userEvent.click(menuClose);
    await expect(menuToggle).toHaveAttribute("aria-expanded", "false");
    await expect(menuPanel?.hidden).toBe(true);
  },
};

const agencyInternetArgs = {
  variant: "agency-internet",
  agencyName: "Department of Corporate and Digital Development",
  agencyLinkType: "custom-url",
  agencyCustomUrl: "https://dcdd.nt.gov.au",
  logoSource: "/src/dxp components/header/previews/mocks/ntg-primary-reverse.svg",
  links: [
    {
      label: "Find online services",
      linkType: "custom-url",
      customUrl: "https://nt.gov.au/services",
    },
    {
      label: "Contacts",
      linkType: "custom-url",
      customUrl: "https://nt.gov.au/contacts",
    },
  ],
};
const agencyInternetHtml = await squiz.markup(agencyInternetArgs);

export const AgencyInternet = {
  render: (args) => withPageContent(args),
  args: agencyInternetArgs,
  argTypes,
  parameters: {
    docs: {
      source: { code: agencyInternetHtml, language: "html", type: "code" },
    },
  },
};
