import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs, mergeDefaultModifiers } from "../_utils/component.helper";

const DEFAULT_LOGO_TEXT = "NT.GOV.AU";
const DEFAULT_LOGO_ALT = "NT.GOV.AU";
const DEFAULT_AGENCY_LOGO_URL =
  "https://dcdd.nt.gov.au/_design/latest/images/ntg-primary-reverse.svg";
const DEFAULT_SEARCH_LABEL = "Search";
const SEARCH_ICON =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true" focusable="false"><path d="M11.5 11.5 15 15M7 12.5A5.5 5.5 0 1 0 7 1.5a5.5 5.5 0 0 0 0 11Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const MENU_ICON =
  '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><path d="M4 7h16M4 12h16M4 17h16" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
const CLOSE_ICON =
  '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
const NTG_HOME_URL = "https://nt.gov.au";

function normalizeSquizLink(source) {
  if (!source) return null;

  if (typeof source === "string") {
    return {
      href: source,
      label: "",
      target: "",
      rel: "",
    };
  }

  if (typeof source !== "object") return null;

  const href =
    source.href ||
    source.url ||
    source.asset_url ||
    source.assetUrl ||
    source.linkUrl ||
    "";
  if (!href) return null;

  const label =
    source.label ||
    source.title ||
    source.name ||
    source.text ||
    source.linkText ||
    "";

  return {
    href: String(href),
    label: String(label || ""),
    target: source.target || "",
    rel:
      source.rel || (source.target === "_blank" ? "noopener noreferrer" : ""),
  };
}

async function normalizeLink(item, fns) {
  if (!item || typeof item !== "object") return null;

  if (typeof item.label === "string") {
    const label = item.label.trim();

    if (label) {
      const linkType = item.linkType === "matrix-asset" ? "matrix-asset" : "custom-url";
      const href =
        linkType === "matrix-asset"
          ? await resolveAssetUrl(item.linkAsset, fns)
          : resolveLinkHref(item.customUrl, "");

      if (href) {
        return {
          href,
          label,
          target: "",
          rel: "",
        };
      }
    }
  }

  const linkSource = Object.prototype.hasOwnProperty.call(item, "link")
    ? item.link
    : item;
  const resolved = normalizeSquizLink(linkSource);
  if (!resolved?.href) return null;

  const explicitLabel = typeof item.label === "string" ? item.label.trim() : "";
  const label = explicitLabel || resolved.label;
  if (!label) return null;

  return { ...resolved, label };
}

function resolveLinkHref(linkValue, fallback = "") {
  const resolved = normalizeSquizLink(linkValue);
  return resolved?.href || fallback;
}

async function resolveLogoSource(logoSource, fns) {
  const source = String(logoSource || "").trim();
  if (!source) return null;

  // Support direct URLs/paths in previews and stories without Matrix URI resolution.
  if (/^(https?:|\/|\.\/|\.\.\/)/i.test(source)) {
    return source;
  }

  if (typeof fns?.resolveUri !== "function") return null;

  try {
    const resolved = await fns.resolveUri(source);
    const asset =
      resolved && typeof resolved === "object" && "data" in resolved
        ? resolved.data
        : resolved;

    if (!asset || typeof asset !== "object") return null;

    return asset.url || (Array.isArray(asset.urls) ? asset.urls[0] : "") || "";
  } catch {
    return null;
  }
}

async function resolveAssetUrl(sourceValue, fns) {
  const source = String(sourceValue || "").trim();
  if (!source) return "";

  if (/^(https?:|\/|\.\/|\.\.\/)/i.test(source)) {
    return source;
  }

  if (typeof fns?.resolveUri !== "function") return "";

  try {
    const resolved = await fns.resolveUri(source);
    const asset =
      resolved && typeof resolved === "object" && "data" in resolved
        ? resolved.data
        : resolved;

    if (!asset || typeof asset !== "object") return "";

    return asset.url || (Array.isArray(asset.urls) ? asset.urls[0] : "") || "";
  } catch {
    return "";
  }
}

function renderLogoImage(logoUrl, logoAlt, extraClass = "") {
  const className = ["ntg-header__logo-image", extraClass]
    .filter(Boolean)
    .join(" ");
  return `<img class="${className}" src="${escURL(logoUrl)}" alt="${escHTML(logoAlt || DEFAULT_LOGO_ALT)}" />`;
}

function renderLogoText(logoText) {
  return `<span class="ntg-header__logo-text">${escHTML(logoText || DEFAULT_LOGO_TEXT)}</span>`;
}

function renderLogoPlaceholder() {
  return '<span class="ntg-header__logo-space" aria-hidden="true"></span>';
}

function renderAgencyName(agencyName) {
  const name = String(agencyName || "").trim();
  if (!name) return "";

  const prefixMatch = /^department of\s+/i.exec(name);
  if (!prefixMatch) {
    return `<span class="ntg-header__agency-name">${escHTML(name)}</span>`;
  }

  const prefix = name.slice(0, prefixMatch[0].length).trimEnd();
  const rest = name.slice(prefixMatch[0].length).trim();

  if (!rest) {
    return `<span class="ntg-header__agency-name">${escHTML(prefix)}</span>`;
  }

  return `<span class="ntg-header__agency-name"><span class="ntg-header__agency-name-prefix">${escHTML(prefix)}</span><span class="ntg-header__agency-name-rest">${escHTML(rest)}</span></span>`;
}

function renderLogo({
  variant,
  resolvedLogoUrl,
  logoAlt,
  logoText,
  logoHref,
  agencyName,
  agencyHref,
}) {
  if (variant === "agency-internet") {
    const variantClass = "ntg-header__brand--agency-internet";
    const agencyLogoUrl = resolvedLogoUrl || DEFAULT_AGENCY_LOGO_URL;
    const agencyBrandContent = agencyLogoUrl
      ? renderLogoImage(
          agencyLogoUrl,
          logoAlt,
          "ntg-header__logo-image--agency",
        )
      : renderLogoPlaceholder();
    return `
    <div class="ntg-header__brand-group ${variantClass}">
      <a class="ntg-header__brand ntg-header__brand--logo plain" href="${escURL(logoHref || NTG_HOME_URL)}" aria-label="${escHTML(logoAlt || logoText || DEFAULT_LOGO_ALT)}">
        ${agencyBrandContent}
      </a>
      ${agencyName ? `<span class="ntg-header__agency-separator" aria-hidden="true"></span><a class="ntg-header__agency-link plain" href="${escURL(agencyHref || logoHref || "/")}">${renderAgencyName(agencyName)}</a>` : ""}
    </div>`;
  }

  const brandContent = resolvedLogoUrl
    ? renderLogoImage(resolvedLogoUrl, logoAlt, "ntg-header__logo-image--mono")
    : renderLogoText(logoText || DEFAULT_LOGO_TEXT);
  return `<a class="ntg-header__brand ntg-header__brand--home plain" href="${escURL(logoHref || NTG_HOME_URL)}" aria-label="${escHTML(logoAlt || logoText || DEFAULT_LOGO_ALT)}">${brandContent}</a>`;
}

function renderLinks(links, options = {}) {
  if (!links.length) return "";

  const {
    navClass = "ntg-header__nav",
    listClass = "ntg-header__nav-list",
    itemClass = "ntg-header__nav-item",
    linkClass = "ntg-header__nav-link",
    textClass = "ntg-header__nav-text",
  } = options;

  const linksHtml = links
    .map((link) => {
      const target = link.target ? ` target="${escHTML(link.target)}"` : "";
      const rel = link.rel ? ` rel="${escHTML(link.rel)}"` : "";
      return `<li class="${itemClass}"><a class="${linkClass}" href="${escURL(link.href)}"${target}${rel}><span class="${textClass}">${escHTML(link.label)}</span></a></li>`;
    })
    .join("\n");

  return `
      <nav class="${navClass}" aria-label="Header links">
        <ul class="${listClass}">
${linksHtml}
        </ul>
      </nav>`;
}

function renderSearch({
  searchAction,
  searchQueryParam,
  searchPlaceholder,
  inputId,
  searchClass = "ntg-header__search",
  searchGroupClass = "ntg-header__search-group",
}) {
  return `
      <form class="${searchClass}" action="${escURL(searchAction)}" method="get" role="search" aria-label="Site search">
        <label class="ntg-header__search-label" for="${inputId}">${DEFAULT_SEARCH_LABEL}</label>
        <div class="${searchGroupClass}">
          <input
            id="${inputId}"
            class="ntg-header__search-input"
            type="search"
            name="${escHTML(searchQueryParam)}"
            placeholder="${escHTML(searchPlaceholder)}"
            value=""
            autocomplete="off"
          />
          <button class="ntg-header__search-button" type="submit" aria-label="${DEFAULT_SEARCH_LABEL}">
            <span class="ntg-header__search-icon" aria-hidden="true">${SEARCH_ICON}</span>
          </button>
        </div>
      </form>`;
}

function renderNtGovAuHeader({
  attrs,
  logoHtml,
  links,
  searchAction,
  searchQueryParam,
  searchPlaceholder,
  instanceId,
}) {
  const hasLinks = links.length > 0;
  const searchPanelId = `ntg-header-search-panel-${instanceId}`;
  const menuPanelId = `ntg-header-menu-panel-${instanceId}`;

  return /*html*/ `
<header ${attrs} class="fullwidth ntg-header ntg-header--nt-gov-au" role="banner" data-header-root>
  <div class="ntg-header__bar">
    <div class="ntg-header__container">
      <div class="ntg-header__primary">
        ${
          hasLinks
            ? `<button class="ntg-header__menu-toggle" type="button" aria-label="Open menu" aria-controls="${menuPanelId}" aria-expanded="false" data-header-menu-toggle>
          <span class="ntg-header__button-icon" aria-hidden="true">${MENU_ICON}</span>
        </button>`
            : ""
        }
        ${logoHtml}
      </div>
      <div class="ntg-header__actions">
        ${renderLinks(links)}
        ${renderSearch({
          searchAction,
          searchQueryParam,
          searchPlaceholder,
          inputId: `ntg-header-search-inline-${instanceId}`,
        })}
        <button class="ntg-header__search-toggle" type="button" aria-label="Open search" aria-controls="${searchPanelId}" aria-expanded="false" data-header-search-toggle>
          <span class="ntg-header__button-icon" aria-hidden="true">${SEARCH_ICON}</span>
        </button>
      </div>
    </div>
  </div>
  <div id="${searchPanelId}" class="ntg-header__search-panel" data-header-search-panel hidden>
    <div class="ntg-header__search-panel-inner">
      ${renderSearch({
        searchAction,
        searchQueryParam,
        searchPlaceholder,
        inputId: `ntg-header-search-panel-${instanceId}`,
        searchClass: "ntg-header__search ntg-header__search--panel",
        searchGroupClass:
          "ntg-header__search-group ntg-header__search-group--panel",
      })}
      <button class="ntg-header__panel-close ntg-header__panel-close--search" type="button" aria-label="Close search" data-header-search-close>
        <span class="ntg-header__button-icon" aria-hidden="true">${CLOSE_ICON}</span>
      </button>
    </div>
  </div>
  ${
    hasLinks
      ? `<div id="${menuPanelId}" class="ntg-header__menu-panel" data-header-menu-panel hidden>
    <button class="ntg-header__menu-backdrop" type="button" aria-label="Close menu" data-header-menu-close></button>
    <div class="ntg-header__menu-drawer">
      <div class="ntg-header__menu-header">
        <button class="ntg-header__panel-close" type="button" aria-label="Close menu" data-header-menu-close>
          <span class="ntg-header__button-icon" aria-hidden="true">${CLOSE_ICON}</span>
        </button>
      </div>
      ${renderLinks(links, {
        navClass: "ntg-header__menu-nav",
        listClass: "ntg-header__menu-list",
        itemClass: "ntg-header__menu-item",
        linkClass: "ntg-header__menu-link",
        textClass: "ntg-header__menu-text",
      })}
    </div>
  </div>`
      : ""
  }
</header>
`;
}

function renderAgencyInternetHeader({
  attrs,
  logoHtml,
  links,
  searchAction,
  searchQueryParam,
  searchPlaceholder,
  instanceId,
}) {
  const searchPanelId = `ntg-header-search-panel-${instanceId}`;

  return /*html*/ `
<header ${attrs} class="ntg-header ntg-header--agency-internet" role="banner" data-header-root>
  <div class="ntg-header__bar">
    <div class="ntg-header__container">
      <div class="ntg-header__primary">
        ${logoHtml}
      </div>
      <div class="ntg-header__actions">
        ${renderLinks(links)}
        ${renderSearch({
          searchAction,
          searchQueryParam,
          searchPlaceholder,
          inputId: `ntg-header-search-inline-${instanceId}`,
        })}
        <button class="ntg-header__search-toggle" type="button" aria-label="Open search" aria-controls="${searchPanelId}" aria-expanded="false" data-header-search-toggle>
          <span class="ntg-header__button-icon" aria-hidden="true">${SEARCH_ICON}</span>
        </button>
      </div>
    </div>
  </div>
  <div id="${searchPanelId}" class="ntg-header__search-panel" data-header-search-panel hidden>
    <div class="ntg-header__search-panel-inner">
      ${renderSearch({
        searchAction,
        searchQueryParam,
        searchPlaceholder,
        inputId: `ntg-header-search-panel-${instanceId}`,
        searchClass: "ntg-header__search ntg-header__search--panel",
        searchGroupClass:
          "ntg-header__search-group ntg-header__search-group--panel",
      })}
      <button class="ntg-header__panel-close ntg-header__panel-close--search" type="button" aria-label="Close search" data-header-search-close>
        <span class="ntg-header__button-icon" aria-hidden="true">${CLOSE_ICON}</span>
      </button>
    </div>
  </div>
</header>
`;
}

export default {
  async main(input = {}, info = {}) {
    const {
      variant = "nt-gov-au",
      logoSource = "",
      logoLink = NTG_HOME_URL,
      agencyName = "",
      agencyHref = "",
      agencyLinkType = "custom-url",
      agencyLinkAsset = "",
      agencyCustomUrl = "",
      logoText = DEFAULT_LOGO_TEXT,
      logoAlt = DEFAULT_LOGO_ALT,
      logoHref = NTG_HOME_URL,
      links = [],
      searchPlaceholder = "Search",
      searchAction = "/search",
      searchQueryParam = "q",
    } = input;
    const instanceId = Math.random().toString(36).slice(2, 8);

    const safeVariant = ["nt-gov-au", "agency-internet"].includes(variant)
      ? variant
      : "nt-gov-au";

    const normalizedLinks = (
      await Promise.all(
        (Array.isArray(links) ? links : []).map((item) =>
          normalizeLink(item, info?.fns),
        ),
      )
    ).filter(Boolean);

    const resolvedLogoUrl =
      safeVariant === "nt-gov-au"
        ? null
        : await resolveLogoSource(logoSource, info?.fns);
    const resolvedLogoHref =
      safeVariant === "nt-gov-au"
        ? NTG_HOME_URL
        : resolveLinkHref(logoLink, logoHref || NTG_HOME_URL);
    const fallbackAgencyHref = resolveLinkHref(
      agencyHref,
      resolvedLogoHref || "/",
    );
    const resolvedAgencyHref =
      safeVariant === "agency-internet"
        ? agencyLinkType === "matrix-asset"
          ? (await resolveAssetUrl(agencyLinkAsset, info?.fns)) ||
            fallbackAgencyHref
          : resolveLinkHref(agencyCustomUrl, fallbackAgencyHref)
        : fallbackAgencyHref;
    const logoHtml = renderLogo({
      variant: safeVariant,
      resolvedLogoUrl,
      logoAlt,
      logoText,
      logoHref: resolvedLogoHref,
      agencyName,
      agencyHref: resolvedAgencyHref,
    });
    const attrs = componentAttrs("header", mergeDefaultModifiers(input, ['fullwidth background']));

    if (safeVariant === "nt-gov-au") {
      return renderNtGovAuHeader({
        attrs,
        logoHtml,
        links: normalizedLinks,
        searchAction,
        searchQueryParam,
        searchPlaceholder,
        instanceId,
      });
    }

    return renderAgencyInternetHeader({
      attrs,
      logoHtml,
      links: normalizedLinks,
      searchAction,
      searchQueryParam,
      searchPlaceholder,
      instanceId,
    });
  },
};
